fn is_ascii_digit(c: char) -> bool {
    // Requires that c is a valid char
    // Ensures that the return value is true if c is between '0' and '9', false otherwise
    // Invariant: c is a char
    // Decreases: None
    assert!(c.is_ascii()); // Assert that c is an ASCII character
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Requires that s is a valid String
    // Ensures that the return value is true if all characters in s are ASCII digits, false otherwise
    // Invariant: s is a String
    // Decreases: None
    assert!(!s.is_empty()); // Assert that s is not empty for the all() method
    s.chars().all(is_ascii_digit)
}

